    x=open(V1+f).read().replace('source42.v1','source42.vN'); y=open(V2+f).read().replace('source42.v2','source42.vN')
    print(f, 'diff after runtime normalization:', [l for l in difflib.unified_diff(x.splitlines(),y.splitlines(),lineterm='',n=0) if l[:1] in '+-'][:12])
O=V2+'output/'
