for p in ['selfcheck/s42-prepost-matrix.json','selfcheck/s42-provenance.json','runs/final-custody.json','blind-review.json','blind-review.md','requirement-status.json']:
    print(p, os.path.exists(O+p), (os.path.getmtime(O+p) if os.path.exists(O+p) else None))
print('checkpoints', sorted(os.listdir(O+'checkpoints')) if os.path.exists(O+'checkpoints') else None)
n=0; files=[]
for d,_,fs in os.walk(O):
    for x in fs:
        if x.endswith('.py'):
            t=open(os.path.join(d,x),errors='replace').read()
            c=t.count('consumer-b.v24-source42.v1')
            if c: n+=c; files.append(os.path.relpath(os.path.join(d,x),O))
print('py files referencing source42.v1:', len(files), 'occurrences', n, 'dirs', sorted({f.split('/')[0] if not f.startswith('preserved') else '/'.join(f.split('/')[:2]) for f in files}))
